export const experimentOptions={"poles": {"a": [["N", "Facing north pole"], ["S", "Facing south pole"]], "b": [["N", "Known north pole"], ["iron", "Unmagnetised iron"]], "labels": ["First object", "Second facing object"], "unit": "interaction", "choices": [["attract", "Attraction"], ["repel", "Repulsion"]]}, "fields": {"a": [["left", "Point beyond left end"], ["right", "Point beyond right end"]], "b": [["normal", "LeftN / rightS"], ["reverse", "LeftS / rightN"]], "labels": ["External axial point", "Magnet orientation"], "unit": "field direction", "choices": [["left", "Left"], ["right", "Right"]]}, "electromagnets": {"a": [["off", "Current off"], ["on", "Current on"]], "b": [["air", "Air core"], ["iron", "Iron core"]], "labels": ["Current", "Core"], "unit": "field comparison", "choices": [["none", "No current-generated field"], ["coil", "Coil field"], ["strong", "Stronger core-assisted field"]]}, "motoreffect": {"a": [["0.2", "0.2 T"], ["0.4", "0.4 T"]], "b": [["2", "2 A"], ["4", "4 A"]], "labels": ["Flux density", "Current (length0.5 m)"], "unit": "N force"}, "motors": {"a": [["normal", "Field reference"], ["reverse", "Field reversed"]], "b": [["normal", "Current reference"], ["reverse", "Current reversed"]], "labels": ["Field", "Current"], "unit": "rotation", "choices": [["cw", "Clockwise reference"], ["ccw", "Anticlockwise"]]}, "speakers": {"a": [["200", "200 Hz"], ["500", "500 Hz"]], "b": [["1", "Original frequency"], ["2", "Double frequency"]], "labels": ["Signal frequency", "Multiplier"], "unit": "Hz cone frequency"}, "induction": {"a": [["in", "Pole moves in"], ["out", "Pole moves out"]], "b": [["N", "North pole"], ["S", "South pole"]], "labels": ["Motion relative to coil", "Pole (north entering =positive)"], "unit": "pulse sign", "choices": [["positive", "Positive reference pulse"], ["negative", "Negative reference pulse"]]}, "generators": {"a": [["alternator", "Alternator: slip rings"], ["dynamo", "Dynamo: split ring"]], "b": [["positive", "Positive coil half-cycle"], ["negative", "Negative coil half-cycle"]], "labels": ["Device", "Uncommutated coil polarity"], "unit": "external polarity", "choices": [["positive", "Positive"], ["negative", "Negative"]]}, "microphones": {"a": [["100", "100 Hz sound"], ["400", "400 Hz sound"]], "b": [["1", "Unchanged frequency"], ["2", "Double frequency"]], "labels": ["Sound frequency", "Multiplier"], "unit": "Hz induced signal"}, "transformers": {"a": [["50", "50 secondary turns"], ["200", "200 secondary turns"]], "b": [["1", "12 V primary"], ["2", "24 V primary"]], "labels": ["Secondary turns (primary100)", "Primary AC voltage"], "unit": "V secondary"}};
export const tasksForMag1=(k,tier="Higher")=>mag1Tasks[k].filter(t=>!t.higher||tier==="Higher");
export const validMag1=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericMag1=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceMag1=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;

export function experimentResult(k,a,b){const o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');const x=Number(a),y=Number(b);let value;
if(k==='poles')value=a===b?'repel':'attract';
if(k==='fields')value=b==='normal'?'left':'right';
if(k==='electromagnets')value=a==='off'?'none':b==='iron'?'strong':'coil';
if(k==='motoreffect')value=x*y*.5;
if(k==='motors')value=a===b?'cw':'ccw';
if(['speakers','microphones'].includes(k))value=x*y;
if(k==='induction')value=(a==='in'&&b==='N')||(a==='out'&&b==='S')?'positive':'negative';
if(k==='generators')value=a==='dynamo'?'positive':b;
if(k==='transformers')value=12*y*x/100;
return{value,a,b};}

export const predictionValid=(k,v,r)=>experimentOptions[k].choices?String(v)===String(r.value):numericMag1(v,r.value);
export const outputLabel=(k,v)=>experimentOptions[k].choices?.find(x=>String(x[0])===String(v))?.[1]??Number(Number(v).toFixed(3))+' '+experimentOptions[k].unit;
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
